import{s as c,n as a}from"../chunks/scheduler.14a511a7.js";import{S as m,i as p,s as h,g as u,x as f,f as n,c as g,h as R,y as k,k as v,a as l}from"../chunks/index.2d17dc57.js";import{b as o}from"../chunks/paths.f4401a76.js";function b(d){let t,e,i=`<div class="wrapper"><div class="page-header  "><h1>Imperial College London Rocketry</h1> <p>The Altitude Record Team (ART) is a project within <a href="https://imperialrocketry.com" target="_blank" rel="noreferrer noopener">Imperial College London Rocketry (ICLR)</a> which exists to break <a href="https://ukra.ork.uk" target="_blank" rel="noreferrer noopener">United Kingdom Rocketry Association (UKRA)</a> altitude records. The team formed in 2019, with its first two launches in early 2021, and our first record-breaking flight in 2022.<br/></p> <p>From 2020-2023, I led the aerodynamics and simulations sub-team, using computational methods to model and optimise the behaviour of our rocket. We used tools including <a href="https://openrocket.info" target="_blank" rel="noreferrer noopener">OpenRocket</a>, <a href="https://www.plm.automation.siemens.com/global/en/products/simcenter/STAR-CCM.html" target="_blank" rel="noreferrer noopener">StarCCM+</a>, and <a href="https://engineering.esteco.com/modefrontier/" target="_blank" rel="noreferrer noopener">ESTECO modeFrontier</a>.</p></div> <div class="project-section  " style="animation-delay: 0.4s;"><h3>ASTRA</h3> <p>This is a family of test-bed rockets used to verify systems in preparation for record-breaking flights. Three successful flights took place during my tenure, testing progressively more advanced systems.</p> <div class="image-container "><img src="${o}/Projects/ICLRResources/ASTRA.png" alt="ASTRA Family"/></div></div> <div class="project-section  " style="animation-delay: 0.6s;"><h3>APEX</h3> <p>The APEX family of rockets are designed to break UKRA altitude records for various motor classes. Rocket motors are classified based on their total impulse (essentially a measure of the &#39;amount of push&#39; they provide). The ICLR Altitude Record Team now holds the record for an I-Class rocket as of 2024.</p> <p><b>APEX I</b> reached 9333ft (3845m) with a single motor, breaking the previous record of 9199ft.</p> <div class="image-container "><img src="${o}/Projects/ICLRResources/APEXI.png" alt="APEX I"/></div></div> <div class="project-section  " style="animation-delay: 1.0s;"><h3>Flight videos</h3> <div class="download-buttons" style="margin-bottom: 0px;"><a href="${o}/Projects/ICLRResources/ASTRA.mp4" target="_blank" rel="noreferrer noopener" class="download-btn ">ASTRA Mk.I, 11.04.2021 (EARS event)</a> <a href="${o}/Projects/ICLRResources/ASTRA2.mp4" target="_blank" rel="noreferrer noopener" class="download-btn ">ASTRA Mk.II, 13.06.2021 (EARS event)</a> <a href="${o}/Projects/ICLRResources/APEX.mp4" target="_blank" rel="noreferrer noopener" class="download-btn ">APEX I, 03.07.2022 (Supported by SARA)</a> <a href="${o}/Projects/ICLRResources/ASTRA3.mp4" target="_blank" rel="noreferrer noopener" class="download-btn ">ASTRA Mk.III, 10.07.2022 (MRC event)</a></div></div> <div class="project-section  " style="animation-delay: 0.8s;"><h3>modeFrontier</h3> <p><a href="https://engineering.esteco.com/modefrontier/" target="_blank" rel="noreferrer noopener">ESTECO</a> kindly provided ICL Rocketry with licenses to use their powerful multidisciplinary optimisation (MDO) software, modeFrontier. This connects with many engineering modelling packages and can be used to optimise complex designs in much shorter timeframes, and with much greater control over simulations, than our previous methods. The team successfully used it to break the I-Class record with APEX-I.</p> <div class="download-buttons" style="margin-bottom: 0px;"><a href="ICLRResources/oR_mF/oRmFIntegration.pdf" target="_blank" rel="noreferrer noopener" class="download-btn ">openRocket-modeFrontier Integration</a> <a href="ICLRResources/oR_mF/NSGA_HYBRID.pdf" target="_blank" rel="noreferrer noopener" class="download-btn ">NSGA-HYBRID Performance Evaluation</a></div></div></div>`;return{c(){t=h(),e=u("main"),e.innerHTML=i,this.h()},l(r){f("svelte-1unz6i6",document.head).forEach(n),t=g(r),e=R(r,"MAIN",{class:!0,"data-svelte-h":!0}),k(e)!=="svelte-veqctc"&&(e.innerHTML=i),this.h()},h(){document.title="Rocketry | N Jenkins",v(e,"class","site-main")},m(r,s){l(r,t,s),l(r,e,s)},p:a,i:a,o:a,d(r){r&&(n(t),n(e))}}}class _ extends m{constructor(t){super(),p(this,t,null,b,c,{})}}export{_ as component};
